import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.BuUvxvtQ.js";const p=JSON.parse('{"title":"Security & Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/security-and-privacy.md","filePath":"web-app/security-and-privacy.md"}'),i={name:"web-app/security-and-privacy.md"};function n(s,e,c,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="security-privacy" tabindex="-1">Security &amp; Privacy <a class="header-anchor" href="#security-privacy" aria-label="Permalink to &quot;Security &amp; Privacy&quot;">​</a></h1><p>Sky Style gives you full control over your account security and your data.</p><h2 id="security-page" tabindex="-1">Security page <a class="header-anchor" href="#security-page" aria-label="Permalink to &quot;Security page&quot;">​</a></h2><p>The <strong>Security</strong> page (<code>/settings/security</code>) protects your account. It is also embedded in the <a href="./account-and-support.html">Account</a> page.</p><h3 id="two-factor-authentication-2fa" tabindex="-1">Two-factor authentication (2FA) <a class="header-anchor" href="#two-factor-authentication-2fa" aria-label="Permalink to &quot;Two-factor authentication (2FA)&quot;">​</a></h3><p>Add a TOTP authenticator (Google Authenticator, Authy, or Bitwarden) for an extra sign-in factor:</p><ol><li>Toggle 2FA on to begin setup.</li><li>Scan the QR code with your authenticator app, or enter the manual key.</li><li>Enter the 6-digit code from your app to verify and enable.</li><li><strong>Save your recovery codes</strong> — they are shown only once. Download them as <code>skystyle-recovery-codes.txt</code> and keep them safe. Each code can be used once.</li></ol><p>After enabling:</p><ul><li><strong>Regenerate</strong> recovery codes at any time — this invalidates the old set (requires a current authenticator code).</li><li><strong>Disable</strong> 2FA by confirming a current code.</li></ul><h3 id="passkeys" tabindex="-1">Passkeys <a class="header-anchor" href="#passkeys" aria-label="Permalink to &quot;Passkeys&quot;">​</a></h3><p>Sign in with a passkey — <strong>Face ID, Touch ID, Windows Hello, or a hardware security key</strong>:</p><ul><li>Register a passkey with a custom name (e.g. &quot;iPhone&quot;).</li><li>List registered passkeys with their creation date and transports.</li><li>Remove any passkey at any time.</li></ul><h3 id="api-keys" tabindex="-1">API keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API keys&quot;">​</a></h3><p>Create and revoke API keys for <a href="./../api/">public API</a> access directly from the Security page:</p><ul><li>Keys are prefixed with <code>sk_live_</code> and shown <strong>only once</strong> at creation — copy immediately.</li><li>View active and revoked keys with their creation date.</li><li>Revoke any key instantly.</li></ul><div class="tip custom-block"><p class="custom-block-title">Full key management</p><p>The <a href="./api-dashboard.html">API Dashboard</a> offers richer key management — nicknames, folders, and credit allocation.</p></div><h3 id="security-log" tabindex="-1">Security log <a class="header-anchor" href="#security-log" aria-label="Permalink to &quot;Security log&quot;">​</a></h3><p>An auditable log of security events on your account:</p><table tabindex="0"><thead><tr><th>Event</th><th>When it appears</th></tr></thead><tbody><tr><td>New sign-in</td><td>Each successful login.</td></tr><tr><td>Signed out</td><td>Each logout.</td></tr><tr><td>Passkey added / removed</td><td>When a passkey is registered or deleted.</td></tr><tr><td>API key created / updated / revoked</td><td>Any API key lifecycle change.</td></tr><tr><td>2FA enabled / disabled</td><td>MFA state changes.</td></tr><tr><td>Recovery codes regenerated</td><td>When the recovery set is replaced.</td></tr><tr><td>Deletion requested / cancelled</td><td>Account deletion lifecycle.</td></tr><tr><td>Data exported</td><td>Each data export.</td></tr></tbody></table><p>Each entry shows the event, the originating IP, and a timestamp.</p><h2 id="privacy-hub" tabindex="-1">Privacy Hub <a class="header-anchor" href="#privacy-hub" aria-label="Permalink to &quot;Privacy Hub&quot;">​</a></h2><p>The <strong>Privacy Hub</strong> (<code>/settings/privacy</code>) controls your data. It is also embedded in the Account page.</p><h3 id="data-export" tabindex="-1">Data export <a class="header-anchor" href="#data-export" aria-label="Permalink to &quot;Data export&quot;">​</a></h3><p>Download everything Sky Style stores about you as a structured JSON file:</p><ul><li>Includes your profile, settings, closet, usage history, feedback, and security logs.</li><li>Human-readable and machine-parseable, with a version stamp and export timestamp.</li></ul><p>Exports are rate-limited: non-Dev accounts can request one export every <strong>12 hours</strong>. A countdown shows when the next export is available.</p><h3 id="account-deletion" tabindex="-1">Account deletion <a class="header-anchor" href="#account-deletion" aria-label="Permalink to &quot;Account deletion&quot;">​</a></h3><p>Request permanent deletion of your account and all associated data:</p><ul><li>This is a <strong>human-reviewed process</strong> — a developer actions it within 7 days.</li><li>Until then, you can <strong>cancel</strong> at any time from the Privacy Hub or the banner shown on the dashboard.</li><li>An optional <strong>reason</strong> (max 1000 characters) helps improve Sky Style.</li></ul><p>While a deletion is pending, a banner appears on the dashboard with quick links to manage the request or contact a developer.</p><div class="warning custom-block"><p class="custom-block-title">Cancellation window</p><p>You retain full access to Sky Style while a deletion request is pending review. Cancelling restores your account to normal immediately.</p></div>',31)])])}const y=t(i,[["render",n]]);export{p as __pageData,y as default};
